insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000013', 'en', null, 'Photography Fundamentals', 'Learn to make deliberate photographs with any camera or phone — from the exposure triangle to composition and light. Built from openly-licensed OER Commons material (CC BY).', null, 'foundations', 19, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000013', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The three controls of the exposure triangle are…","options":["aperture, shutter speed, ISO","focus, zoom, flash","hue, saturation, contrast","aperture, focal length, white balance"],"answer":0,"explanation":"Aperture, shutter speed, and ISO together set the brightness of an image — see ''The exposure triangle''."},{"prompt":"A wider aperture (a smaller f-number like f/2.8) lets in…","options":["less light","more light","the same light","no light"],"answer":1,"explanation":"A smaller f-number means a bigger opening and more light — see ''Aperture''."},{"prompt":"A fast shutter speed such as 1/1000 s is best for…","options":["blurring a waterfall","freezing fast motion","shooting in the dark","increasing grain"],"answer":1,"explanation":"Fast shutter speeds freeze motion — see ''Motion''."},{"prompt":"Raising ISO makes the image brighter but also adds…","options":["sharpness","digital noise (grain)","depth of field","warmth"],"answer":1,"explanation":"Higher ISO amplifies the signal and the noise with it — see ''ISO''."},{"prompt":"To blur the background behind a portrait, you want a…","options":["narrow aperture like f/16","wide aperture like f/2.8","high ISO","fast shutter"],"answer":1,"explanation":"A wide aperture gives shallow depth of field — see ''Depth of field''."},{"prompt":"The rule of thirds suggests placing key subjects…","options":["dead center","along the lines or intersections of a 3x3 grid","at the very edge","always at the bottom"],"answer":1,"explanation":"Off-center placement usually feels more dynamic — see ''Composition''."},{"prompt":"The ''golden hour'' refers to…","options":["midday sun","the hour after sunrise and before sunset","any hour indoors","the brightest hour of the day"],"answer":1,"explanation":"Low, warm, soft light shortly after sunrise or before sunset — see ''Light''."},{"prompt":"A longer focal length (a telephoto lens) tends to…","options":["widen the view","compress distance and narrow the view","add grain","brighten the image"],"answer":1,"explanation":"Telephoto lenses magnify and compress — see ''Focus and lenses''."}]}'::jsonb, null, 10),
  (2, 'How a camera sees: the exposure triangle', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the three exposure controls and say what each does to brightness. Warm-up: from the diagnostic, which control also adds grain when you push it up?"},{"heading":"The idea","text":"A photograph is a measured amount of light landing on a sensor (or film). Three controls set that amount. *Aperture* is the size of the lens opening, written as an f-number: a *smaller* number (f/2.8) means a *wider* opening and *more* light; a larger number (f/16) means a narrow opening and less light. *Shutter speed* is how long the sensor is exposed: 1/1000 s is brief and dark, 1/30 s is long and bright. *ISO* is how strongly the signal is amplified: higher ISO brightens the image but adds noise. Photographers measure changes in *stops* — one stop doubles or halves the light."},{"heading":"Worked example","text":"You shoot at f/2.8 and the picture is bright but the background is too blurry, so you close the aperture to f/8. That is three stops (f/2.8 → f/4 → f/5.6 → f/8), cutting the light to one-eighth. To keep the same brightness you must add three stops back: slow the shutter from 1/500 s to about 1/60 s, or raise ISO from 100 to 800. The exposure is unchanged; only the trade-offs moved."},{"heading":"Your turn","text":"Answer each: (1) You go from f/4 to f/5.6 — more or less light? (2) You want a brighter photo without touching aperture or shutter — which control do you raise? (3) 1/1000 s vs 1/60 s: which is brighter? (4) The downside of a high ISO is ___. Answers: (1) less (one stop smaller opening), (2) ISO, (3) 1/60 s, (4) noise/grain."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a bigger f-number means more light — it is the opposite. Mistake: chasing brightness with ISO first when slowing the shutter would keep the image cleaner. Exit: (a) Which f-number lets in more light, f/2.8 or f/11? (b) Going from ISO 100 to ISO 400 is how many stops brighter? Answers: f/2.8; two stops."}]}'::jsonb, 'Every exposure is a trade: change one control, compensate with another.', 12),
  (3, 'Depth of field and motion', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Predict how aperture affects background blur and how shutter speed affects moving subjects. Warm-up: which control did you use in the last lesson to blur a background?"},{"heading":"The idea","text":"Each exposure control has a *side effect* you can use creatively. Aperture sets *depth of field* — how much of the scene is in sharp focus. A wide aperture (f/2.8) gives *shallow* depth of field: the subject is sharp and the background melts away. A narrow aperture (f/16) gives *deep* depth of field: foreground to horizon stays sharp, ideal for landscapes. Shutter speed sets how motion is rendered. A fast shutter (1/1000 s) *freezes* a runner; a slow shutter (1/15 s) lets them *blur*, showing movement. On a phone, ''Portrait mode'' fakes shallow depth of field in software."},{"heading":"Worked example","text":"A portrait at f/8 shows a distracting fence behind your subject in focus. Open to f/2.8 and that fence dissolves into smooth blur — the eye now goes straight to the face. For a waterfall, 1/1000 s freezes every droplet, while 1/2 s on a steady support turns the water into a silky ribbon."},{"heading":"Your turn","text":"Answer each: (1) Sharp landscape, front to back — wide or narrow aperture? (2) Creamy blurred background — which f-number, f/2 or f/16? (3) Freeze a jumping dog — fast or slow shutter? (4) Show the motion streak of car headlights at night — fast or slow shutter? Answers: (1) narrow (e.g. f/16), (2) f/2, (3) fast, (4) slow."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming a wide aperture always looks better — a group photo at f/2 may leave the back row soft. Mistake: hand-holding a slow shutter and getting accidental blur; brace the camera or raise ISO. Exit: (a) Which gives more of the scene in focus, f/4 or f/11? (b) To freeze a sprinter, do you want a fast or slow shutter? Answers: f/11; fast."}]}'::jsonb, 'Aperture also controls background blur; shutter speed also controls motion blur.', 12),
  (4, 'Composition: arranging the frame', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply the rule of thirds, leading lines, and framing to strengthen a shot. Warm-up: think of a photo you liked — was the subject dead-center or off to one side?"},{"heading":"The idea","text":"Composition is how you place elements inside the frame. The *rule of thirds* splits the frame with two horizontal and two vertical lines; placing a subject on a line or intersection usually feels more balanced than centering it. *Leading lines* — a road, a fence, a shoreline — guide the viewer''s eye toward the subject. *Framing* uses foreground shapes such as a doorway or branches to surround the subject and add depth. These are tools, not laws: break them on purpose once you know why they work."},{"heading":"Worked example","text":"A lone tree centered in a wide field feels static. Move it to the left-third line and let the empty field open to the right, and the image gains room to breathe. Add a dirt path entering from the bottom corner as a leading line, and the eye travels from the path straight to the tree."},{"heading":"Your turn","text":"Answer each: (1) A grid of two horizontal and two vertical lines is the rule of ___. (2) A river curving toward a mountain is an example of a ___ line. (3) Shooting a portrait through an archway is called ___. (4) True or false: centering a subject is always wrong. Answers: (1) thirds, (2) leading, (3) framing, (4) false — centering can work for symmetry, it is just not automatic."},{"heading":"Common mistakes & exit ticket","text":"Mistake: cramming everything in and forgetting negative space — empty areas give the subject room. Mistake: a tilted horizon; keep it level unless the tilt is deliberate. Exit: (a) Name one technique that guides the eye toward the subject. (b) Where does the rule of thirds suggest placing a key subject? Answers: leading lines (or framing); on a third line or intersection."}]}'::jsonb, 'Composition is where things sit in the frame — decide it before you press the shutter.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Going from f/2.8 to f/8 does what to the light?","options":["increases it three stops","reduces it three stops","leaves it unchanged","doubles it"],"answer":1,"explanation":"Higher f-number = narrower opening; f/2.8→f/8 is three stops darker."},{"prompt":"Which setting gives the shallowest depth of field?","options":["f/16","f/8","f/2","f/11"],"answer":2,"explanation":"The widest aperture (smallest f-number) blurs the background most."},{"prompt":"To freeze a bird in flight you should use a…","options":["slow shutter","fast shutter","narrow aperture","low ISO"],"answer":1,"explanation":"Fast shutter speeds stop motion."},{"prompt":"The rule of thirds recommends placing subjects…","options":["in the exact center","on grid lines or their intersections","at the frame''s edge","below the horizon"],"answer":1,"explanation":"Off-center placement on the thirds grid usually feels balanced."},{"prompt":"Raising ISO from 100 to 800 makes the photo brighter but…","options":["sharper","noisier","wider","warmer"],"answer":1,"explanation":"Higher ISO amplifies noise along with the signal."},{"prompt":"A winding road drawing the eye toward a subject is a…","options":["framing element","leading line","vignette","confounding line"],"answer":1,"explanation":"Leading lines direct the viewer''s gaze."}]}'::jsonb, null, 8),
  (6, 'Working with light', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how the direction and quality of light change a photo, and use golden hour. Warm-up: is midday sun usually soft or harsh?"},{"heading":"The idea","text":"Light has a *quality* and a *direction*. Soft light (an overcast sky, open shade) wraps gently and hides blemishes; hard light (direct midday sun) makes sharp, dark shadows. Direction changes everything: *front light* is flat and even, *side light* rakes across a surface to reveal texture and shape, and *back light* puts the source behind the subject for silhouettes or a glowing rim. The *golden hour*, shortly after sunrise or before sunset, gives low, warm, soft, directional light that flatters almost any subject."},{"heading":"Worked example","text":"A face photographed at noon has harsh shadows under the eyes and nose. Move the person into open shade and the light softens instantly. For a landscape, the same hill looks flat under front light at midday but gains three-dimensional depth at golden hour, when side light throws long shadows that model every ridge."},{"heading":"Your turn","text":"Answer each: (1) Overcast sky gives soft or hard light? (2) To emphasize the texture of tree bark, which direction — front or side light? (3) A subject rimmed with a bright glowing edge is lit from the ___. (4) Warm, low, soft light near sunset is called the ___ hour. Answers: (1) soft, (2) side, (3) back, (4) golden."},{"heading":"Common mistakes & exit ticket","text":"Mistake: shooting portraits in harsh midday sun and getting squints and deep shadows — seek shade or wait for softer light. Mistake: ignoring where the light comes from and only asking whether there is enough. Exit: (a) Which direction of light best reveals texture? (b) Name the flattering warm hour near sunrise/sunset. Answers: side light; golden hour."}]}'::jsonb, 'Photography is drawing with light — its quality and direction matter as much as its amount.', 12),
  (7, 'Focus and lenses', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain focal length and choose where to focus. Warm-up: does a telephoto lens make distant things bigger or smaller?"},{"heading":"The idea","text":"*Focal length* (in millimeters) sets your *angle of view*. A short focal length (a 24 mm wide lens) captures a broad scene and exaggerates the sense of depth — great for landscapes and tight spaces. A long focal length (a 200 mm telephoto) narrows the view, magnifies distant subjects, and *compresses* the space between them — great for wildlife and portraits. *Focus* decides which plane is sharp; missing focus is the most common way a photo fails. Autofocus works best when you place the focus point on your subject — for people, focus on the eyes."},{"heading":"Worked example","text":"A 24 mm shot of a canyon makes the near rocks loom huge and the far wall tiny, stretching depth. Switch to 200 mm from farther back and the same wall fills the frame while layers of ridges stack together, compressed and flattened. For a portrait, lock focus on the near eye at f/2.8 and the far ear may already be soft — that is normal shallow depth of field."},{"heading":"Your turn","text":"Answer each: (1) Wide sweeping landscape — short or long focal length? (2) A distant eagle filling the frame — wide or telephoto? (3) On a portrait, focus on the ___. (4) Which lens compresses distance between subjects? Answers: (1) short/wide, (2) telephoto, (3) eyes, (4) telephoto (long focal length)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: letting the camera focus on the background instead of the subject — set the focus point yourself. Mistake: expecting a phone''s wide lens to flatter a face up close; step back or use a longer setting to avoid distortion. Exit: (a) A 200 mm lens gives a wide or narrow angle of view? (b) On a portrait, what should be sharpest? Answers: narrow; the eyes."}]}'::jsonb, 'Focal length changes your angle of view; focus decides what is sharp.', 11),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"aperture","translation":"the size of the lens opening, set by f-number; a smaller f-number is a wider opening","example":"At f/2.8 the wide aperture blurred the background."},{"term":"shutter speed","translation":"how long the sensor is exposed to light; faster freezes motion, slower blurs it","example":"1/1000 s froze the splashing water."},{"term":"ISO","translation":"the sensor''s sensitivity/amplification; higher brightens the image but adds noise","example":"In the dim room she raised ISO to 3200."},{"term":"stop","translation":"a unit that doubles or halves the light; the common currency of the exposure triangle","example":"Closing from f/4 to f/5.6 is one stop less light."},{"term":"depth of field","translation":"how much of the scene is in acceptably sharp focus, controlled mainly by aperture","example":"A narrow aperture gave deep depth of field across the landscape."},{"term":"golden hour","translation":"the period just after sunrise or before sunset when light is low, warm, and soft","example":"They shot the portraits during golden hour for flattering light."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"One ''stop'' of exposure means the light is…","options":["increased by 10%","doubled or halved","unchanged","tripled"],"answer":1,"explanation":"A stop doubles or halves the light."},{"prompt":"Side light is especially good for revealing…","options":["texture and shape","background blur","digital noise","focal length"],"answer":0,"explanation":"Raking side light emphasizes surface texture."},{"prompt":"A 24 mm lens compared with a 200 mm lens gives a…","options":["narrower view","wider view","brighter view","sharper view"],"answer":1,"explanation":"Shorter focal length = wider angle of view."},{"prompt":"For a landscape sharp from front to back, choose…","options":["f/2","f/2.8","f/16","the highest ISO"],"answer":2,"explanation":"A narrow aperture gives deep depth of field."},{"prompt":"On a portrait, you should place focus on the…","options":["background","eyes","hands","nearest corner"],"answer":1,"explanation":"Sharp eyes anchor a portrait."},{"prompt":"Harsh midday sun is best described as…","options":["soft light","hard light","back light only","golden hour"],"answer":1,"explanation":"Direct overhead sun makes hard, sharp-edged shadows."}]}'::jsonb, null, 8),
  (10, 'Applied project: plan a 5-shot photo series', 'writing', '{"sections":[{"heading":"The task","text":"Plan and describe a five-shot photo series on one theme (for example ''my street at dusk'', ''hands at work'', or ''water''). You can shoot it with any camera or phone. You will not be graded on the images — you will be graded on the deliberate choices you write down for each shot."},{"heading":"Milestones","text":"For each of the five shots, state: (1) the subject and the composition technique you''ll use (rule of thirds, leading lines, or framing); (2) your exposure intent — aperture for depth of field (deep or shallow) and shutter speed for motion (freeze or blur), plus roughly what ISO the light demands; (3) the light you''ll use (direction and quality, e.g. side light in golden hour); (4) where you''ll place focus. Make the five shots vary — mix at least one shallow-depth and one deep-depth image, and one that freezes motion with one that blurs it."},{"heading":"Self-check rubric","text":"✔ Each shot names a composition technique and justifies it. ✔ Aperture and shutter choices are consistent with the effect described (e.g. shallow depth of field pairs with a wide aperture like f/2.8, not f/16). ✔ ISO reflects the lighting realistically (low in bright light, higher in dim light). ✔ The series shows variety in depth of field and motion and a clear focus point per shot. If all four are true, you are thinking like a photographer, not just pointing and shooting."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000013' and l.position = v.pos
);
